SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(p.props, '$.archetype.person_id')) AS SIGNED), JSON_UNQUOTE(JSON_EXTRACT(p.props, '$.archetype.firstName')) , JSON_UNQUOTE(JSON_EXTRACT(p.props, '$.archetype.lastName')) FROM ( SELECT e.dst AS id FROM anchors e WHERE e.src = ? AND e.kind = 'EdgeAnchor' AND e.arch_type = 'Knows' UNION ALL SELECT e.src AS id FROM anchors e WHERE e.dst = ? AND e.kind = 'EdgeAnchor' AND e.arch_type = 'Knows' ) f JOIN anchors p ON p.id = f.id AND p.kind = 'NodeAnchor' AND p.arch_type = 'Person' ORDER BY CAST(JSON_UNQUOTE(JSON_EXTRACT(p.props, '$.archetype.person_id')) AS SIGNED)
